window.HOEREN_TESTS[22] = {"id":"wetter-und-jahreszeiten","name":"Wetter und Jahreszeiten","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Und nun das Wetter für die ganze Woche. Heute Montag und Dienstag noch sonnig und warm, bis zu 25 Grad. Am Mittwoch ändert sich das Wetter komplett — Regen und starker Wind. Donnerstag und Freitag bleibt es kühl und bewölkt. Erst am Wochenende wird es wieder sonnig.","gender":"f","q":"Wann ändert sich das Wetter zum Schlechteren?","opts":["Am Mittwoch.","Am Wochenende.","Am Dienstag."],"correct":0},{"transcript":"Achtung an die Skifahrer in den Alpen: Wegen starkem Schneefall wurden mehrere Pisten gesperrt. Die roten und schwarzen Pisten sind ab heute Mittag nicht zugänglich. Blaue Pisten sind sicher und geöffnet. Wir empfehlen Anfängern, im Tal zu bleiben — auch dort gibt es genug Möglichkeiten. Viel Spaß!","gender":"m","q":"Welche Pisten sind heute offen?","opts":["Nur blaue.","Rote und schwarze.","Alle."],"correct":0},{"transcript":"Hi Schatz, hier ist Mama. Pass auf, wegen unserem Wochenend-Ausflug ans Meer: Das Wetter wird schlecht — Regen und Wind. Trotzdem ans Meer fahren ist keine gute Idee, und nur zu Hause bleiben ist auch schade. Statt ans Meer könnten wir nach München fahren, ins Deutsche Museum. Drinnen, trocken. Oder wir verschieben den Strandausflug. Sag deine Meinung, ich warte auf deinen Anruf.","gender":"f","q":"Was schlägt Mama vor?","opts":["Trotzdem ans Meer fahren.","Zu Hause bleiben.","Ins Deutsche Museum."],"correct":2},{"transcript":"Liebe Hörer, der Sommer wird dieses Jahr sehr heiß. Meteorologen erwarten Temperaturen bis zu 38 Grad im August. Bitte trinken Sie viel, vermeiden Sie Sonne zwischen 12 und 16 Uhr. Pflanzen und Tiere brauchen besonders viel Wasser. Auch viele alte Menschen leiden bei der Hitze — bitte kümmern Sie sich um Verwandte.","gender":"f","q":"Wann ist die Sonne am gefährlichsten?","opts":["Am Morgen.","Zwischen 12 und 16 Uhr.","Am Abend."],"correct":1},{"transcript":"Hallo Lukas, hier ist Anna. Der Skiausflug am Sonntag — die Schneebedingungen sind schlecht. Nur 30 Zentimeter Schnee, das reicht nicht. Statt zu fahren, möchten wir lieber wandern. Es schneit nicht mehr in dieser Saison. Schade, schreib mir, ob wandern okay ist oder ob du anders entscheidest.","gender":"f","q":"Was schlägt Anna vor?","opts":["Trotzdem Ski fahren.","Stattdessen wandern.","Den Ausflug absagen."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch zwischen Anna und Markus. Sie planen, was sie in welcher Jahreszeit machen wollen. Sie hören den Text einmal. Was machen sie in welcher Jahreszeit? Wählen Sie für jede Jahreszeit einen Buchstaben (a–i).","lines":[{"speaker":"Anna","gender":"f","text":"Hallo Markus! Wir wollen das Jahr mit schönen Plänen füllen."},{"speaker":"Markus","gender":"m","text":"Das ist eine schöne Idee. Vier Jahreszeiten und danach noch das Fest im Dezember."},{"speaker":"Anna","gender":"f","text":"In den Bergen wandern wir im Frühling. Die Wege sind dann grün und ruhig."},{"speaker":"Markus","gender":"m","text":"Wandern mag ich sehr. Sollen wir irgendwann einen Marathon laufen?"},{"speaker":"Anna","gender":"f","text":"Nein. Einen Marathon laufen wir nicht. Dafür fehlt uns einfach die Ausdauer."},{"speaker":"Markus","gender":"m","text":"Wann haben wir Zeit für eine Reise mit viel Sonne und warmem Wasser?"},{"speaker":"Anna","gender":"f","text":"Ans Meer fahren wir im Sommer. Wir wollen baden und lange in der Sonne liegen."},{"speaker":"Markus","gender":"m","text":"Der große Korb steht schon im Schrank bereit."},{"speaker":"Anna","gender":"f","text":"Pilze sammeln wir im Herbst. Wir nehmen nur die sicheren Sorten mit."},{"speaker":"Markus","gender":"m","text":"Die Reise in den Schnee ist noch offen. Wann fahren wir endlich los?"},{"speaker":"Anna","gender":"f","text":"Skifahren in Österreich machen wir im Winter. Der Schnee liegt dort meist sicher."},{"speaker":"Markus","gender":"m","text":"Wollen wir Fahrrad fahren als großes Projekt durch das Land?"},{"speaker":"Anna","gender":"f","text":"Nein. Fahrrad fahren steht dieses Jahr nicht an. Die Strecke ist uns zu lang."},{"speaker":"Markus","gender":"m","text":"Und was machen wir bei dem Fest am Ende des Jahres?"},{"speaker":"Anna","gender":"f","text":"Zu Hause mit der Familie bleiben wir an Weihnachten. Wir essen lange zusammen und singen."},{"speaker":"Markus","gender":"m","text":"Das ist mir von allem am wichtigsten."}],"options":[{"letter":"a","text":"Eis essen"},{"letter":"b","text":"Garten umgraben"},{"letter":"c","text":"in den Bergen wandern"},{"letter":"d","text":"Marathon laufen"},{"letter":"e","text":"Fahrrad fahren"},{"letter":"f","text":"Skifahren in Österreich"},{"letter":"g","text":"Pilze sammeln"},{"letter":"h","text":"zu Hause mit Familie"},{"letter":"i","text":"ans Meer fahren"}],"items":[{"person":"Frühling","correct":"c"},{"person":"Sommer","correct":"i"},{"person":"Herbst","correct":"g"},{"person":"Winter","correct":"f"},{"person":"Weihnachten","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, soll ich heute eine Jacke mitnehmen? Eine normale, oder lieber etwas gegen Regen?"},{"speaker":"Vater","gender":"m","text":"Ja, der Wetterbericht hat Regen am Nachmittag gesagt. Auch ein Schirm wäre nicht schlecht, eine normale Jacke wird nass."},{"speaker":"Tochter","gender":"f","text":"Schirm habe ich nicht in der Tasche. Aber meine Regenjacke nehme ich mit, nicht die normale."},{"speaker":"Vater","gender":"m","text":"Gut, Regenjacke ist besser als Schirm. Dann bleibst du trocken."},{"speaker":"Tochter","gender":"f","text":"Okay, ich packe die Regenjacke ein. Bis später!"}],"q":"Was nimmt die Tochter mit?","opts":["Regenjacke.","Eine normale Jacke.","Einen Schirm."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Schatz, wir gehen heute baden, oder? Das Wasser ist bestimmt schön."},{"speaker":"Frau","gender":"f","text":"Hast du das Wetter geprüft? 18 Grad, ziemlich kühl. Zu Hause bleiben müssen wir nicht."},{"speaker":"Mann","gender":"m","text":"18 ist zu kalt zum Baden. Aber einen Spaziergang machen ist okay, nicht nur zu Hause sitzen."},{"speaker":"Frau","gender":"f","text":"Spaziergang dann! Baden verschieben wir, und zu Hause bleiben wir nicht den ganzen Tag."},{"speaker":"Mann","gender":"m","text":"Einverstanden, Jacke an und raus. Das wird schön."}],"q":"Was machen sie heute?","opts":["Baden gehen.","Einen Spaziergang machen.","Zu Hause bleiben."],"correct":1},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, im Winter machen wir doch Schlittenfahren? Morgen sicher, oder nur vielleicht?"},{"speaker":"Mutter","gender":"f","text":"Ja, wenn es genug Schnee gibt. Sicher fahren wir nicht, und absagen tun wir auch nicht."},{"speaker":"Sohn","gender":"m","text":"Es schneit heute! Können wir morgen sicher los?"},{"speaker":"Mutter","gender":"f","text":"Erst mal sehen, ob der Schnee bleibt. Wenn ja, dann vielleicht Schlitten fahren."},{"speaker":"Sohn","gender":"m","text":"Okay, ich schaue morgen früh aus dem Fenster. Ich hoffe, der Schnee bleibt."}],"q":"Was machen sie morgen?","opts":["Sicher nicht Schlitten fahren.","Sicher Schlitten fahren.","Vielleicht Schlitten fahren, wenn Schnee bleibt."],"correct":2},{"lines":[{"speaker":"Kollege","gender":"m","text":"Es ist so heiß heute, schon 35 Grad! Sollen wir nach Hause gehen?"},{"speaker":"Kollegin","gender":"f","text":"Schrecklich. Im Büro funktioniert die Klimaanlage nicht. Nach Hause ist zu früh, die Arbeit ist nicht fertig."},{"speaker":"Kollege","gender":"m","text":"Lass uns nach 15 Uhr im Park arbeiten — mit Laptop. Da ist es kühler als im Büro."},{"speaker":"Kollegin","gender":"f","text":"Gute Idee, nicht im Büro bleiben und nicht nach Hause, sondern im Park arbeiten."},{"speaker":"Kollege","gender":"m","text":"Genau, ich packe den Laptop ein. Bis gleich im Park."}],"q":"Was machen die Kollegen?","opts":["Im Park arbeiten.","Im Büro bleiben.","Nach Hause gehen."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Was ziehst du heute zum Bewerbungsgespräch an? Einen Anzug, oder etwas Leichtes?"},{"speaker":"Mann","gender":"m","text":"Anzug, klar. Aber bei 30 Grad ist der dunkle schwere furchtbar. Gar keinen Anzug anzuziehen ist zu sportlich."},{"speaker":"Frau","gender":"f","text":"Nimm den hellen Sommer-Anzug, das ist atmungsaktiver. Nicht den dunklen schweren."},{"speaker":"Mann","gender":"m","text":"Gute Idee, den hellen ziehe ich an. Kein schwerer Anzug und nicht ohne Anzug."},{"speaker":"Frau","gender":"f","text":"Perfekt, so siehst du seriös aus und schwitzt nicht so."}],"q":"Welchen Anzug zieht der Mann an?","opts":["Den dunklen schweren.","Den hellen Sommer-Anzug.","Gar keinen Anzug."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Kirsch, einem Meteorologen. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Kirsch, Sie sind Meteorologe seit 25 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Kirsch","gender":"m","text":"Schon als Kind war ich vom Wetter fasziniert. Stürme, Schnee, Sonne — alles hat mich begeistert. Mit 14 habe ich schon eine kleine Wetterstation zu Hause gebaut und jeden Tag Aufzeichnungen gemacht. Meteorologie zu studieren war dann logisch."},{"speaker":"Reporter","gender":"m","text":"Wie hat sich das Wetter in 25 Jahren verändert?"},{"speaker":"Kirsch","gender":"m","text":"Sehr stark. Die Sommer sind heißer geworden, die Winter milder. Stürme häufiger und stärker. Wir merken den Klimawandel ganz klar. Das, was wir vor 25 Jahren ‚außergewöhnliches Wetter‘ nannten, ist heute normal."},{"speaker":"Reporter","gender":"m","text":"Können Sie das Wetter wirklich genau vorhersagen?"},{"speaker":"Kirsch","gender":"m","text":"Für die nächsten 3 Tage ja, ziemlich genau. Für eine Woche schon weniger sicher. Für 14 Tage kann ich nur Tendenzen sagen. Aber wir werden immer besser — die Computer helfen sehr."},{"speaker":"Reporter","gender":"m","text":"Was ist Ihre Lieblings-Wettersituation?"},{"speaker":"Kirsch","gender":"m","text":"Ein klassisches Gewitter im Sommer — mit Donner und Blitz. Schön zu beobachten, wenn man sicher drinnen ist. Schnee mag ich auch sehr, aber Stürme sind faszinierend."},{"speaker":"Reporter","gender":"m","text":"Wie ist Ihre Arbeit als Meteorologe im Alltag?"},{"speaker":"Kirsch","gender":"m","text":"Viel Bildschirmarbeit. Daten analysieren, Modelle prüfen, dann Vorhersagen erstellen. Das ist eigentlich keine romantische Arbeit — viel mehr Mathematik und Statistik, als die Leute denken."}],"items":[{"q":"Herr Kirsch hat schon als Kind Wetter beobachtet.","correct":"ja"},{"q":"Die Sommer sind in den letzten 25 Jahren kühler geworden.","correct":"nein"},{"q":"Wetter-Vorhersagen für 3 Tage sind ziemlich genau.","correct":"ja"},{"q":"Er findet seine Arbeit sehr romantisch.","correct":"nein"},{"q":"Stürme findet er faszinierend.","correct":"ja"}]}]};
